def merge_ranges(ranges):
    """Merge [start, end] pairs that overlap or touch; return them sorted."""
    pairs = sorted([start, end] for start, end in ranges)
    out = []
    for start, end in pairs:
        if out and start <= out[-1][1]:
            if end > out[-1][1]:
                out[-1][1] = end
        else:
            out.append([start, end])
    return out


def total_length(ranges):
    """Total length covered by the ranges, counting overlaps once."""
    covered = 0
    for start, end in merge_ranges(list(ranges)):
        covered += end - start
    return covered

